def main():
    logs = [
        '2024-01-15 INFO: system started',
        '2024-01-15 ERROR: disk full',
        '2024-01-15 ERROR: memory low',
        '2024-01-15 WARNING: high CPU'
    ]
    error_msgs = (line.split('ERROR: ')[1] for line in logs if 'ERROR' in line)
    for _ in range(3):
        try:
            print(next(error_msgs))
        except StopIteration:
            break

if __name__ == '__main__':
    main()

